    graph = defaultdict(list)

    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        # Generate all departure times: l, l+d, l+2d, ..., l+(k-1)d
        for i in range(k):
            departure_time = l + i * d
            graph[A].append((departure_time, B, c))

    # f(s) = latest arrival time at station N from station s
    f = {}
    for s in range(1, N+1):
        f[s] = -10**18

    # Process stations in reverse order from N-1 down to 1
    for s in range(N-1, 0, -1):
        for departure_time, dest, travel_time in graph[s]:
            if dest == N:
                # Direct arrival at destination N
                arrival_time = departure_time + travel_time
                f[s] = max(f[s], arrival_time)
            else:
                # Go through intermediate station
                if f[dest] != -10**18:
                    # Total arrival time at N
                    total_arrival_time = departure_time + travel_time + f[dest]
